// Support file for this exercise only.
// The printed program uses ArrayDeque without importing java.util.ArrayDeque,
// so this thin stand-in in the same package supplies the name. In your own
// code, add "import java.util.ArrayDeque;" at the top of the file instead.
public class ArrayDeque<E> extends java.util.ArrayDeque<E> {
    private static final long serialVersionUID = 1L;
}
